"use client"

import { useEffect, useState } from "react"
import { useNavigate } from "react-router-dom"
import axios from "axios"
import {
  ChefHat,
  GraduationCap,
  Building2,
  DollarSign,
  TrendingUp,
  AlertCircle,
  Loader2,
  ArrowUpRight,
  Eye,
  FileText,
  Package,
} from "lucide-react"
import Layout from "./Layout"

// Import Chart.js components for Doughnut chart
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from "chart.js"
import { Doughnut } from "react-chartjs-2"

// Register Chart.js components
ChartJS.register(ArcElement, Tooltip, Legend)

export default function Dashboard() {
  const [stats, setStats] = useState({
    totalInterns: 0,
    totalChefs: 0,
    totalDeputyDirectors: 0,
    totalPayments: 0,
    totalReports: 0,
    recentReports: [],
    recentPayments: [],
    paymentsByMonth: [],
    paymentCompletion: 0,
    internsBySector: [],
    consumption: {
      total: 0,
      academicYear: "N/A",
    },
    payments: {
      total: 0,
      numberOfInterns: 0,
      averagePerIntern: 0,
      academicYear: "N/A",
      monthlyBreakdown: {},
    },
    inventory: {
      products: 0,
      lowStock: 0,
      expired: 0,
      recent: [],
    },
  })
  const navigate = useNavigate()
  const [userRole, setUserRole] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState("")

  // Helper function to parse DD/MM/YYYY or ISO dates
  const parseDate = (dateStr) => {
    if (!dateStr) return null
    // Try parsing as ISO first
    let parsedDate = new Date(dateStr)
    if (!isNaN(parsedDate)) return parsedDate
    // Try parsing as DD/MM/YYYY
    const [day, month, year] = dateStr.split("/")
    if (!day || !month || !year) return null
    parsedDate = new Date(`${year}-${month}-${day}`)
    return isNaN(parsedDate) ? null : parsedDate
  }

  useEffect(() => {
    const token = localStorage.getItem("token")
    const role = localStorage.getItem("role")
    if (!token || !role) {
      navigate("/")
    } else {
      setUserRole(role)
      fetchDashboardData(token)
    }
  }, [navigate])

  const fetchDashboardData = async (token) => {
    setIsLoading(true)
    setError("")
    try {
      const [
        internsResponse,
        chefsResponse,
        directorsResponse,
        reportsResponse,
        paymentsResponse,
        consumptionResponse,
        totalPaymentsResponse,
        inventoryResponse,
      ] = await Promise.all([
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/interns`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: { data: [] } })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/chefs`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: [] })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/deputydirectors`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: [] })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/reports`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: { data: [] } })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/payments`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: { data: [] } })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/interns/totalConsumption`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({
            data: { data: { totalConsumption: 0, academicYear: "N/A" } },
          })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/payments/total`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({
            data: {
              data: { totalAmount: 0, numberOfInterns: 0, averagePerIntern: 0, monthlyBreakdown: {} },
            },
          })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/products`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: [] })),
      ])

      const interns = internsResponse.data.data || []
      const chefs = chefsResponse.data || []
      const directors = directorsResponse.data || []
      const reports = reportsResponse.data.data || []
      const payments = paymentsResponse.data.data || []
      const consumption = consumptionResponse.data.data || {}
      const totalPayments = totalPaymentsResponse.data.data || {}
      const inventoryData = inventoryResponse.data || []

      // Process inventory data
      const today = new Date()
      today.setHours(0, 0, 0, 0) // Normalize to start of day

      const lowStockProducts = inventoryData.filter((product) => product.quantity < 50)
      const expiredProducts = inventoryData.filter((product) => {
        if (!product.expirationDate) return false
        const expiryDate = parseDate(product.expirationDate)
        if (!expiryDate) {
          console.log(`Invalid expiration date for product ${product.nameProduct}: ${product.expirationDate}`)
          return false
        }
        return expiryDate < today
      })
      const recentProducts = inventoryData.slice(0, 5).map((product) => ({
        id: product._id,
        name: product.nameProduct,
        quantity: product.quantity,
        price: product.priceForOne,
        expiryDate: product.expirationDate
          ? parseDate(product.expirationDate)?.toLocaleDateString("fr-FR") || "N/A"
          : "N/A",
      }))

      // Log for debugging
      console.log("Expired Products:", expiredProducts)
      console.log("Low Stock Products:", lowStockProducts)

      // Process other data
      const sectors = {}
      interns.forEach((intern) => {
        if (intern.Sector) {
          sectors[intern.Sector] = (sectors[intern.Sector] || 0) + 1
        }
      })
      const internsBySector = Object.keys(sectors).map((key) => ({
        name: key,
        value: sectors[key],
      }))

      const totalMonths = payments.length * 12
      let paidMonths = 0
      payments.forEach((payment) => {
        if (payment.payments) {
          Object.values(payment.payments).forEach((amount) => {
            if (amount > 0) paidMonths++
          })
        }
      })
      const paymentCompletion = totalMonths > 0 ? Math.round((paidMonths / totalMonths) * 100) : 0

      const recentReports = reports.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)).slice(0, 5)
      const recentPayments = payments.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)).slice(0, 5)

      const monthlyPayments = totalPayments.monthlyBreakdown || {}
      const paymentsByMonth = [
        monthlyPayments.September || 0,
        monthlyPayments.October || 0,
        monthlyPayments.November || 0,
        monthlyPayments.December || 0,
        monthlyPayments.January || 0,
        monthlyPayments.February || 0,
        monthlyPayments.March || 0,
        monthlyPayments.April || 0,
        monthlyPayments.May || 0,
        monthlyPayments.June || 0,
        monthlyPayments.July || 0,
        monthlyPayments.August || 0,
      ]

      setStats({
        totalInterns: interns.length,
        totalChefs: chefs.length,
        totalDeputyDirectors: directors.length,
        totalPayments: payments.reduce((sum, payment) => sum + (payment.totalAmount || 0), 0),
        totalReports: reports.length,
        recentReports,
        recentPayments,
        paymentsByMonth,
        paymentCompletion,
        internsBySector,
        consumption: {
          total: consumption.totalConsumption || 0,
          academicYear: consumption.academicYear || "N/A",
        },
        payments: {
          total: totalPayments.totalAmount || 0,
          numberOfInterns: totalPayments.numberOfInterns || 0,
          averagePerIntern: totalPayments.averagePerIntern || 0,
          academicYear: totalPayments.academicYear || "N/A",
          monthlyBreakdown: totalPayments.monthlyBreakdown || {},
        },
        inventory: {
          products: inventoryData.length,
          lowStock: lowStockProducts.length,
          expired: expiredProducts.length,
          recent: recentProducts,
        },
      })
    } catch (err) {
      console.error("Dashboard data fetch error:", err)
      setError("Failed to load dashboard data. Please try again later.")
    } finally {
      setIsLoading(false)
    }
  }

  // Inventory Doughnut chart data
  const inventoryStatusData = {
    labels: ["Stock suffisant", "Stock faible", "Expiré"],
    datasets: [
      {
        data: [
          stats.inventory.products - stats.inventory.lowStock - stats.inventory.expired,
          stats.inventory.lowStock,
          stats.inventory.expired,
        ],
        backgroundColor: [
          "rgba(76, 175, 80, 0.6)", // Stock suffisant (green)
          "rgba(255, 159, 64, 0.6)", // Stock faible (orange)
          "rgba(255, 99, 132, 0.6)", // Expiré (red)
        ],
        borderColor: [
          "rgba(76, 175, 80, 1)",
          "rgba(255, 159, 64, 1)",
          "rgba(255, 99, 132, 1)",
        ],
        borderWidth: 1,
      },
    ],
  }

  if (isLoading) {
    return (
      <Layout>
        <div className="flex flex-col items-center justify-center h-64">
          <Loader2 className="h-10 w-10 text-[#00717F] animate-spin mb-4" />
          <p className="text-[#333333]">Chargement du tableau de bord...</p>
        </div>
      </Layout>
    )
  }

  if (error) {
    return (
      <Layout>
        <div className="p-6 bg-red-50 border-l-4 border-red-500 rounded-md mb-6">
          <div className="flex items-center">
            <AlertCircle className="h-6 w-6 text-red-500 mr-3" />
            <p className="text-red-700">{error}</p>
          </div>
        </div>
      </Layout>
    )
  }

  return (
    <Layout>
      <div className="space-y-6">
        {/* Welcome Header */}
        <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] rounded-xl p-6 text-white shadow-lg">
          <h1 className="text-2xl font-bold">Bienvenue, Directeur pédagogique</h1>
          <p className="mt-1 text-white/80">
            Voici un aperçu de l'activité de l'Hôtel Pédagogique ISTA Benguérir - Année{" "}
            {stats.consumption.academicYear || stats.payments.academicYear}
          </p>
          <div className="mt-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-3 mr-3">
                <GraduationCap className="h-6 w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-sm">Stagiaires</p>
                <p className="text-2xl font-bold">{stats.totalInterns}</p>
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-3 mr-3">
                <ChefHat className="h-6 w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-sm">Cuisiniers</p>
                <p className="text-2xl font-bold">{stats.totalChefs}</p>
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-3 mr-3">
                <DollarSign className="h-6 w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-sm">Paiements</p>
                <p className="text-2xl font-bold">{stats.payments.total} DH</p>
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-3 mr-3">
                <FileText className="h-6 w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-sm">Consommation</p>
                <p className="text-2xl font-bold">{stats.consumption.total} DH</p>
              </div>
            </div>
          </div>
        </div>

        {/* Main Dashboard Content */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Charts Section */}
          <div className="lg:col-span-2 space-y-6">
            {/* Payment Amount Chart - Candle Style */}
            <div className="bg-[#F5F6FA] rounded-xl shadow-md p-6 border border-[#C8A45D]/30">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-lg font-bold text-[#00717F]">
                  Paiements Mensuels ({stats.payments.academicYear})
                </h2>
                <div className="flex items-center text-sm text-[#4CAF50] font-medium">
                  <TrendingUp className="h-4 w-4 mr-1" />
                  <span>Total: {stats.payments.total} DH</span>
                </div>
              </div>
              <div className="h-64 w-full relative">
                <div className="flex h-full items-end justify-around">
                  {stats.paymentsByMonth.map((amount, index) => {
                    const isPositive = amount > 0
                    return (
                      <div key={index} className="flex flex-col items-center w-16">
                        <div className="text-xs font-medium text-[#00717F] mb-1">
                          {amount > 0 ? `${amount} DH` : ""}
                        </div>
                        <div className="relative w-12 flex flex-col justify-end">
                          <div
                            className={`w-12 rounded-sm ${isPositive ? "bg-[#4CAF50]" : "bg-gray-300"}`}
                            style={{
                              height: `${Math.max((amount / 2400) * 190)}px`,
                            }}
                          ></div>
                        </div>
                        <div className="text-xs text-[#333333] mt-4">
                          {["Sep", "Oct", "Nov", "Déc", "Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Aoû"][
                            index
                          ]}
                        </div>
                      </div>
                    )
                  })}
                </div>
              </div>
            </div>

            {/* Payment Tracking */}
            <div className="bg-[#F5F6FA] rounded-xl shadow-md p-6 border border-[#C8A45D]/30">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-lg font-bold text-[#00717F]">Suivi des Paiements</h2>
                <button
                  onClick={() => navigate("/PaymentTrackingPourSuperadmin")}
                  className="text-sm text-[#00717F] hover:text-[#C8A45D] font-medium flex items-center"
                >
                  Voir tout <ArrowUpRight className="h-4 w-4 ml-1" />
                </button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <h3 className="text-sm font-medium text-[#333333]">Taux de Complétion</h3>
                    <span className="text-sm text-[#333333]">{stats.paymentCompletion}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2.5">
                    <div
                      className="bg-[#00717F] h-2.5 rounded-full"
                      style={{ width: `${stats.paymentCompletion}%` }}
                    ></div>
                  </div>
                  <div className="flex justify-between text-xs text-[#333333]">
                    <span>0%</span>
                    <span>50%</span>
                    <span>100%</span>
                  </div>
                </div>
                <div className="space-y-4">
                  <h3 className="text-sm font-medium text-[#333333]">Paiements Récents</h3>
                  <ul className="space-y-3">
                    {stats.recentPayments.slice(0, 3).map((payment, index) => (
                      <li key={index} className="flex items-center justify-between text-sm">
                        <div className="flex items-center">
                          <div className="h-8 w-8 rounded-full bg-[#F5F6FA] flex items-center justify-center mr-2">
                            <DollarSign className="h-4 w-4 text-[#00717F]" />
                          </div>
                          <span className="font-medium">
                            {payment.internId?.First_Name} {payment.internId?.Last_Name}
                          </span>
                        </div>
                        <span className="font-semibold text-[#4CAF50]">{payment.totalAmount} DH</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>

            {/* Gestion du Stock Section */}
            <div className="bg-[#F5F6FA] rounded-xl shadow-md border border-[#C8A45D]/30 overflow-hidden">
              <div className="bg-[#F5F6FA]/50 p-4">
                <div className="flex items-center gap-2">
                  <Package className="h-5 w-5 text-[#00717F]" />
                  <h2 className="text-lg font-semibold text-[#00717F]">Gestion du Stock</h2>
                </div>
              </div>
              <div className="p-4">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                  <div className="bg-[#F5F6FA]/50 p-3 rounded-lg">
                    <div className="flex items-center gap-2 mb-1">
                      <Package className="h-4 w-4 text-[#00717F]" />
                      <h3 className="text-sm font-medium text-[#333333]">Total Produits</h3>
                    </div>
                    <p className="text-2xl font-bold text-[#00717F]">{stats.inventory.products}</p>
                  </div>
                  <div className="bg-orange-50 p-3 rounded-lg">
                    <div className="flex items-center gap-2 mb-1">
                      <AlertCircle className="h-4 w-4 text-orange-600" />
                      <h3 className="text-sm font-medium text-[#333333]">Stock Faible</h3>
                    </div>
                    <p className="text-2xl font-bold text-orange-600">{stats.inventory.lowStock}</p>
                  </div>
                  <div className="bg-red-50 p-3 rounded-lg">
                    <div className="flex items-center gap-2 mb-1">
                      <AlertCircle className="h-4 w-4 text-red-600" />
                      <h3 className="text-sm font-medium text-[#333333]">Expiré</h3>
                    </div>
                    <p className="text-2xl font-bold text-red-600">{stats.inventory.expired}</p>
                  </div>
                </div>
                <div className="mb-4">
                  <h3 className="text-sm font-medium text-[#333333] mb-2">État du stock</h3>
                  <div className="h-48">
                    <Doughnut
                      data={inventoryStatusData}
                      options={{
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { legend: { position: "right" } },
                      }}
                    />
                  </div>
                </div>
                <div className="mt-6">
                  <div className="flex justify-between items-center mb-2">
                    <h3 className="text-sm font-medium text-[#333333]">Produits récents</h3>
                    <button
                      onClick={() => navigate("/ManageProductsPourSuperadmin")}
                      className="text-xs text-[#00717F] hover:text-[#C8A45D] flex items-center gap-1"
                    >
                      Voir tous <ArrowUpRight className="h-3 w-3" />
                    </button>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-[#C8A45D]/30">
                      <thead>
                        <tr className="text-left text-xs font-medium text-[#333333] uppercase tracking-wider">
                          <th className="px-4 py-2">Produit</th>
                          <th className="px-4 py-2">Quantité</th>
                          <th className="px-4 py-2">Prix</th>
                          <th className="px-4 py-2">Expiration</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-[#C8A45D]/20">
                        {stats.inventory.recent.map((product) => (
                          <tr key={product.id} className="hover:bg-[#F5F6FA]/30 transition-colors">
                            <td className="px-4 py-2 text-sm text-[#333333]">{product.name}</td>
                            <td className="px-4 py-2 text-sm text-[#333333]">{product.quantity}</td>
                            <td className="px-4 py-2 text-sm text-[#333333]">{product.price} DH</td>
                            <td className="px-4 py-2 text-sm text-[#333333]">{product.expiryDate}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Right Sidebar */}
          <div className="space-y-6">
            {/* Interns by Sector */}
            <div className="bg-[#F5F6FA] rounded-xl shadow-md p-6 border border-[#C8A45D]/30">
              <h2 className="text-lg font-bold text-[#00717F] mb-4">Stagiaires par Secteur</h2>
              <div className="space-y-4">
                {stats.internsBySector.map((sector, index) => (
                  <div key={index} className="space-y-2">
                    <div className="flex justify-between items-center">
                      <span className="text-sm font-medium text-[#333333]">{sector.name}</span>
                      <span className="text-sm text-[#333333]">{sector.value}</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-[#00717F] h-2 rounded-full"
                        style={{ width: `${(sector.value / stats.totalInterns) * 100}%` }}
                      ></div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Recent Reports */}
            <div className="bg-[#F5F6FA] rounded-xl shadow-md p-6 border border-[#C8A45D]/30">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-bold text-[#00717F]">Rapports Récents</h2>
                <div className="flex space-x-2">
                  <button
                    onClick={() => navigate("/ChefReports")}
                    className="text-xs text-[#00717F] hover:text-[#C8A45D] font-medium"
                  >
                    Cuisiniers
                  </button>
                  <button
                    onClick={() => navigate("/InternReports")}
                    className="text-xs text-[#00717F] hover:text-[#C8A45D] font-medium"
                  >
                    Stagiaires
                  </button>
                  <button
                    onClick={() => navigate("/DirectorReports")}
                    className="text-xs text-[#00717F] hover:text-[#C8A45D] font-medium"
                  >
                    Gestionnaires
                  </button>
                </div>
              </div>
              <ul className="space-y-3">
                {stats.recentReports.map((report, index) => {
                  let icon, bgColor, name
                  if (report.submitterRole === "Chef") {
                    icon = <ChefHat className="h-4 w-4" />
                    bgColor = "bg-amber-100 text-amber-800"
                    name = report.chefId ? `${report.chefId.firstName} ${report.chefId.lastName}` : "Chef inconnu"
                  } else if (report.submitterRole === "intern") {
                    icon = <GraduationCap className="h-4 w-4" />
                    bgColor = "bg-green-100 text-green-800"
                    name = report.internId
                      ? `${report.internId.First_Name} ${report.internId.Last_Name}`
                      : "Stagiaire inconnu"
                  } else {
                    icon = <Building2 className="h-4 w-4" />
                    bgColor = "bg-blue-100 text-blue-800"
                    name = report.deputyDirectorId ? report.deputyDirectorId.name : "Gestionnaire inconnu"
                  }
                  return (
                    <li key={index} className="p-3 bg-gray-50 rounded-lg hover:bg-[#F5F6FA]/50 transition-colors">
                      <div className="flex justify-between items-start">
                        <div className="flex-1">
                          <div className="flex items-center mb-1">
                            <span
                              className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${bgColor} mr-2`}
                            >
                              {icon}
                              <span className="ml-1">{report.submitterRole}</span>
                            </span>
                            <span className="text-xs text-[#333333]">
                              {new Date(report.createdAt).toLocaleDateString("fr-FR")}
                            </span>
                          </div>
                          <p className="text-sm text-[#333333] line-clamp-1">{report.description}</p>
                          <p className="text-xs text-[#333333] mt-1">{name}</p>
                        </div>
                        <button
                          className="ml-2 p-1 text-[#333333] hover:text-[#00717F] rounded-full hover:bg-[#F5F6FA] transition-colors"
                          onClick={() => {
                            if (report.submitterRole === "Chef") {
                              navigate("/ChefReports")
                            } else if (report.submitterRole === "intern") {
                              navigate("/InternReports")
                            } else {
                              navigate("/DirectorReports")
                            }
                          }}
                        >
                          <Eye className="h-4 w-4" />
                        </button>
                      </div>
                    </li>
                  )
                })}
              </ul>
            </div>

            {/* Quick Actions */}
            <div className="bg-[#F5F6FA] rounded-xl shadow-md p-6 border border-[#C8A45D]/30">
              <h2 className="text-lg font-bold text-[#00717F] mb-4">Actions Rapides</h2>
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={() => navigate("/Chefs")}
                  className="p-3 bg-[#F5F6FA] hover:bg-[#C8A45D]/20 rounded-lg flex flex-col items-center justify-center transition-colors"
                >
                  <ChefHat className="h-6 w-6 text-[#00717F] mb-1" />
                  <span className="text-xs font-medium text-[#00717F]">Cuisiniers</span>
                </button>
                <button
                  onClick={() => navigate("/Deputydirectors")}
                  className="p-3 bg-[#F5F6FA] hover:bg-[#C8A45D]/20 rounded-lg flex flex-col items-center justify-center transition-colors"
                >
                  <Building2 className="h-6 w-6 text-[#00717F] mb-1" />
                  <span className="text-xs font-medium text-[#00717F]">Gestionnaires</span>
                </button>
                <button
                  onClick={() => navigate("/InternsPourSuperadmin")}
                  className="p-3 bg-[#F5F6FA] hover:bg-[#C8A45D]/20 rounded-lg flex flex-col items-center justify-center transition-colors"
                >
                  <GraduationCap className="h-6 w-6 text-[#00717F] mb-1" />
                  <span className="text-xs font-medium text-[#00717F]">Stagiaires</span>
                </button>
                <button
                  onClick={() => navigate("/PaymentTrackingPourSuperadmin")}
                  className="p-3 bg-[#F5F6FA] hover:bg-[#C8A45D]/20 rounded-lg flex flex-col items-center justify-center transition-colors"
                >
                  <DollarSign className="h-6 w-6 text-[#00717F] mb-1" />
                  <span className="text-xs font-medium text-[#00717F]">Paiements</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  )
}
